import{_ as o,o as l,c,a5 as d}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"反射：框架设计的灵魂","description":"","frontmatter":{"title":"反射：框架设计的灵魂","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","核心API","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第三部分：核心 API/08-反射/反射：框架设计的灵魂.md","filePath":"posts/java快速入门/第三部分：核心 API/08-反射/反射：框架设计的灵魂.md"}'),t={name:"posts/java快速入门/第三部分：核心 API/08-反射/反射：框架设计的灵魂.md"};function i(s,e,a,r,u,p){return l(),c("div",null,[...e[0]||(e[0]=[d('<div><p>**反射：**将类的各个组成部分封装为其他对象，这就是反射机制 <code>*</code> 好处： <code>1.</code> 可以在程序运行过程中，操作这些对象。 <code>2.</code> 可以解耦，提高程序的可扩展性。</p><p><strong>获取</strong><code>Class</code><strong>对象的方式：</strong><code>1. Class.forName(&quot;</code>全类名<code>&quot;)</code>：将字节码文件加载进内存，返回<code>Class</code>对象 <code>*</code> 多用于配置文件，将类名定义在配置文件中。读取文件，加载类 <code>2.</code> 类名<code>.class</code>：通过类名的属性<code>class</code>获取 <code>*</code> 多用于参数的传递 <code>3.</code> 对象<code>.getClass()</code>：<code>getClass()</code>方法在<code>Object</code>类中定义着。 <code>*</code> 多用于对象的获取字节码的方式</p><p>结论：同一个字节码文件<code>(*.class)</code>在一次程序运行过程中，只会被加载一次，不论通过哪一种方式获取的<code>Class</code>对象都是同一个。</p><p><code>Class</code><strong>对象功能：</strong><code>*</code> 获取功能： <code>1.</code> 获取成员变量们 <code>* Field[] getFields()</code> ：获取所有<code>public</code>修饰的成员变量 <code>* Field getField(String name)</code> 获取指定名称的 <code>public</code>修饰的成员变量 <code>* Field[] getDeclaredFields()</code> 获取所有的成员变量，不考虑修饰符 <code>* Field getDeclaredField(String name)</code></p><p><code>2.</code> 获取构造方法们</p><ul><li><ul><li>Constructor&lt;?&gt;[] getConstructors()</li></ul></li><li><ul><li>Constructor&lt;T&gt; getConstructor(</li></ul></li></ul><p>类</p><ul><li>&lt;?&gt;... parameterTypes)</li><li><ul><li>Constructor&lt;T&gt; getDeclaredConstructor(</li></ul></li></ul><p>类</p><ul><li>&lt;?&gt;... parameterTypes)</li><li><ul><li>Constructor&lt;?&gt;[] getDeclaredConstructors()</li></ul></li></ul><p><code>3.</code> 获取成员方法们：</p><ul><li><ul><li>Method[] getMethods()</li></ul></li><li><ul><li>Method getMethod(String name,</li></ul></li></ul><p>类</p><ul><li>&lt;?&gt;... parameterTypes)</li><li><ul><li>Method[] getDeclaredMethods()</li></ul></li><li><ul><li>Method getDeclaredMethod(String name,</li></ul></li></ul><p>类</p><ul><li>&lt;?&gt;... parameterTypes)</li><li><ol start="4"><li></li></ol></li></ul><p>获取全类名</p><p><code>* String getName()</code></p><p><code>Field</code>：成员变量 <code>*</code> 操作： <code>1.</code> 设置值</p><ul><li>void set(Object obj, Object value)</li></ul><ol start="2"><li></li></ol><p>获取值</p><ul><li><ul><li>get(Object obj)</li></ul></li><li><ol start="3"><li></li></ol></li></ul><p>忽略访问权限修饰符的安全检查 <code>* setAccessible(true):</code>暴力反射 <code>* Constructor:</code>构造方法 <code>*</code> 创建对象：</p><ul><li><ul><li>T newInstance(Object... initargs)</li></ul></li><li><ul><li></li></ul></li></ul><p>如果使用空参数构造方法创建对象，操作可以简化：<code>Class</code>对象的<code>newInstance</code>方法 <code>* Method</code>：方法对象 <code>*</code> 执行方法：</p><ul><li><ul><li>Object invoke(Object obj, Object... args)</li></ul></li><li><ul><li></li></ul></li></ul><p>获取方法名称： <code>* String getName:</code>获取方法名</p><p><strong>案例：</strong> 需求：写一个<code>&quot;</code>框架<code>&quot;</code>，不能改变该类的任何代码的前提下，可以帮我们创建任意类的对象，并且执行其中任意方法 <code>*</code> 实现： <code>1.</code> 配置文件 <code>2.</code> 反射 <code>*</code> 步骤： <code>1.</code> 将需要创建的对象的全类名和需要执行的方法定义在配置文件中 <code>2.</code> 在程序中加载读取配置文件 <code>3.</code> 使用反射技术来加载类文件进内存 <code>4.</code> 创建对象 <code>5.</code> 执行方法</p></div>',1)])])}const _=o(t,[["render",i]]);export{g as __pageData,_ as default};
